    {
      "id": "c16",
      "correctAnswer": "D",
      "reward": 50,
      "country": "PL",
      "version": "challenge-evidence-pl-en-v1-c30-draft",
      "author": "daily_author",
      "created_date": "2026-10-16",
      "reviewer": "daily_data_review",
      "learning_goal": "Compare survey measurements without converting declared trust into a safety or wealth certificate.",
      "copy": {
        "pl": {
          "id": "c16",
          "question": "Która lista jest najpełniejsza przy porównywaniu ankiet o zaufaniu do instytucji finansowych?",
          "answers": [
            {
              "id": "A",
              "text": "Tylko nagłówek publikacji"
            },
            {
              "id": "B",
              "text": "Tylko rok, bez informacji o próbie"
            },
            {
              "id": "C",
              "text": "Liczba polubień publikacji"
            },
            {
              "id": "D",
              "text": "Rok, próba, treść pytania i metoda pomiaru"
            }
          ],
          "correctAnswer": "D",
          "explanation": "Sprawdź, kogo i kiedy badano, o co pytano oraz jak liczono wynik. Różne pytania lub próby ograniczają porównywalność. Deklarowane zaufanie nie jest certyfikatem bezpieczeństwa konkretnej instytucji ani dowodem wpływu na majątek.",
          "reward": 50,
          "category": "Wyzwanie"
        },
        "en": {
          "id": "c16",
          "question": "Which checklist is most complete when comparing surveys of trust in financial institutions?",
          "answers": [
            {
              "id": "A",
              "text": "Only the publication headline"
            },
            {
              "id": "B",
              "text": "Only the year, without sample information"
            },
            {
              "id": "C",
              "text": "The number of likes on the publication"
            },
            {
              "id": "D",
              "text": "Year, sample, question wording and measurement method"
            }
          ],
          "correctAnswer": "D",
          "explanation": "Check who was surveyed, when, what was asked and how the result was calculated. Different questions or samples limit comparability. Declared trust is not a certificate that a particular institution is safe or proof of an effect on wealth.",
          "reward": 50,
          "category": "Deep Dive"
        }
      },
      "wrong_option_explanations": {
        "A": {
          "pl": "Nagłówek nie zastępuje opisu próby, pytania ani metody.",
          "en": "A headline does not replace the sample, question or method description."
        },
        "B": {
          "pl": "Rok jest przydatny, ale sama data nie wystarcza do rzetelnego porównania różnych pytań i prób.",
          "en": "The year is useful, but a date alone cannot establish comparability across questions and samples."
        },
        "C": {
          "pl": "Popularność publikacji nie wyjaśnia, jak i kogo badano.",
          "en": "Publication popularity does not explain how or whom researchers surveyed."
        }
      },
      "source_ids": [
        "oecd-poland-2022",
        "oecd-toolkit-2026"
      ],
      "calculation_assumptions": {
        "currency": null,
        "new_population_percentage": null,
        "trust_not_safety_or_wealth_effect": true,
        "compare_year_sample_item_method": true
      }
    },
    {
      "id": "c17",
      "correctAnswer": "B",
      "reward": 50,
      "country": "PL",
      "version": "challenge-evidence-pl-en-v1-c30-draft",
      "author": "daily_author",
      "created_date": "2026-10-16",
      "reviewer": "daily_data_review",
      "learning_goal": "Interpret a hypothetical score gap as points, not financial outcomes or a current OECD scale.",
      "copy": {
        "pl": {
          "id": "c17",
          "question": "Ćwiczenie: w wymyślonej skali 0–21 pkt uzyskano 13 pkt. Co oznacza różnica do maksimum?",
          "answers": [
            {
              "id": "A",
              "text": "8 utraconych szans na zysk"
            },
            {
              "id": "B",
              "text": "8 punktów według przyjętego klucza, nie diagnozę majątku"
            },
            {
              "id": "C",
              "text": "8 miesięcy bez pieniędzy"
            },
            {
              "id": "D",
              "text": "8 osób bez konta"
            }
          ],
          "correctAnswer": "B",
          "explanation": "21 − 13 = 8 punktów w tym ćwiczeniu. To wymyślona skala, nie aktualna skala OECD; punkty nie oznaczają liczby pytań. Same punkty nie dowodzą zachowania, zadłużenia, odporności ani przyczyn problemów. Wynik badania wymaga roku, próby, pytań i klucza; wersje pomiaru mogą się różnić.",
          "reward": 50,
          "category": "Wyzwanie"
        },
        "en": {
          "id": "c17",
          "question": "Exercise: a made-up 0–21-point scale gives a score of 13. What does the gap to the maximum mean?",
          "answers": [
            {
              "id": "A",
              "text": "8 lost opportunities for profit"
            },
            {
              "id": "B",
              "text": "8 points under the chosen scoring key, not a wealth diagnosis"
            },
            {
              "id": "C",
              "text": "8 months without money"
            },
            {
              "id": "D",
              "text": "8 people without an account"
            }
          ],
          "correctAnswer": "B",
          "explanation": "21 − 13 = 8 points in this exercise. This made-up scale is not the current OECD scale; points are not a count of questions. Points alone prove neither behaviour, debt, resilience nor the causes of difficulties. Survey results need a year, sample, questions and scoring key; measurement versions can differ.",
          "reward": 50,
          "category": "Deep Dive"
        }
      },
      "wrong_option_explanations": {
        "A": {
          "pl": "Punktów nie przelicza się automatycznie na utracone okazje ani zysk.",
          "en": "Points do not automatically translate into lost opportunities or profit."
        },
        "C": {
          "pl": "Jednostką ćwiczenia są punkty, nie miesiące utrzymania.",
          "en": "The exercise uses points, not months of living expenses."
        },
        "D": {
          "pl": "Różnica punktowa nie określa liczby osób ani posiadania konta.",
          "en": "The point gap is not a count of people or account ownership."
        }
      },
      "source_ids": [
        "oecd-poland-2022",
        "oecd-toolkit-2022",
        "oecd-toolkit-2026"
      ],
      "calculation_assumptions": {
        "currency": null,
        "made_up_point_scale": true,
        "minimum": 0,
        "maximum": 21,
        "score": 13,
        "gap": 8,
        "units": "points",
        "not_current_OECD_scale": true,
        "not_question_count": true,
        "no_population_or_causal_outcome_claim": true
      }
    },
    {
      "id": "c18",
      "correctAnswer": "C",
      "reward": 50,
      "country": "PL",
      "version": "challenge-evidence-pl-en-v1-c30-draft",
      "author": "daily_author",
      "created_date": "2026-10-16",
      "reviewer": "daily_data_review",
      "learning_goal": "Choose an affordable voluntary action without promising stress elimination or blaming financial circumstances.",
      "copy": {
        "pl": {
          "id": "c18",
          "question": "Ćwiczenie: w tym miesiącu po podstawowych potrzebach i wymaganych minimalnych spłatach zostaje 50 zł. Który krok jest dobrowolny i mieści się w tej kwocie?",
          "answers": [
            {
              "id": "A",
              "text": "Pożyczyć 100 zł, by koniecznie odłożyć 100"
            },
            {
              "id": "B",
              "text": "Pominąć wymaganą spłatę"
            },
            {
              "id": "C",
              "text": "Wybrać 10 zł na rezerwę i zostawić 40 zł"
            },
            {
              "id": "D",
              "text": "Założyć, że mały przelew usunie cały stres"
            }
          ],
          "correctAnswer": "C",
          "explanation": "50 − 10 = 40 zł w tym samym miesiącu; podstawy i wymagane spłaty uwzględniono już raz. Mały krok jest opcją, nie obowiązkiem ani gwarancją braku stresu. Gdy nie ma nadwyżki, wstrzymaj wpłatę; nie pożyczaj na oszczędzanie. Przy zmiennym dochodzie wróć do planu i dostosuj kwotę.",
          "reward": 50,
          "category": "Wyzwanie"
        },
        "en": {
          "id": "c18",
          "question": "Exercise: this month, PLN 50 remains after essential needs and required minimum repayments. Which step is voluntary and fits within that amount?",
          "answers": [
            {
              "id": "A",
              "text": "Borrow PLN 100 to make a compulsory saving of 100"
            },
            {
              "id": "B",
              "text": "Skip a required repayment"
            },
            {
              "id": "C",
              "text": "Choose PLN 10 for a reserve and leave PLN 40"
            },
            {
              "id": "D",
              "text": "Assume a small transfer will remove all stress"
            }
          ],
          "correctAnswer": "C",
          "explanation": "50 − 10 = PLN 40 in the same month; essentials and required repayments were already counted once. A small step is an option, not a duty or a guarantee of no stress. Without a surplus, pause contributions; do not borrow to save. When income varies, return to the plan and adjust the amount.",
          "reward": 50,
          "category": "Deep Dive"
        }
      },
      "wrong_option_explanations": {
        "A": {
          "pl": "Cel oszczędzania nie uzasadnia wymuszania nowego długu ani obowiązkowej wpłaty.",
          "en": "A savings goal does not justify forcing new debt or a compulsory contribution."
        },
        "B": {
          "pl": "Wymaganych spłat nie pomija się, aby wykonać dobrowolny przelew na rezerwę.",
          "en": "Required repayments are not skipped to make an optional reserve transfer."
        },
        "D": {
          "pl": "Jedna czynność nie gwarantuje zniknięcia stresu ani kontroli nad wszystkimi okolicznościami.",
          "en": "One action guarantees neither the removal of stress nor control over all circumstances."
        }
      },
      "source_ids": [
        "cfpb-emergency",
        "cfpb-wellbeing"
      ],
      "calculation_assumptions": {
        "currency": "PLN",
        "period": "same month",
        "hypothetical": true,
        "surplus_after_essential_needs_and_required_minimum_repayments": 50,
        "optional_transfer": 10,
        "remainder": 40,
        "required_minimum_repayments_already_counted_once": true,
        "no_surplus_pause": true,
        "irregular_income_adjust": true,
        "no_borrowing_to_save": true,
        "no_guaranteed_psychological_or_financial_effect": true
      }
    },
    {
      "id": "c19",
      "correctAnswer": "B",
      "reward": 50,
      "country": "PL",
      "version": "challenge-evidence-pl-en-v1-c30-draft",
      "author": "daily_author",
      "created_date": "2026-10-16",
      "reviewer": "daily_data_review",
      "learning_goal": "Recognize an emergency reserve and adapt a voluntary target to circumstances.",
      "copy": {
        "pl": {
          "id": "c19",
          "question": "Który termin oznacza środki odłożone na nagłe, nieplanowane wydatki?",
          "answers": [
            {
              "id": "A",
              "text": "Pensja za bieżącą pracę"
            },
            {
              "id": "B",
              "text": "Poduszka finansowa"
            },
            {
              "id": "C",
              "text": "Wymagana pożyczka na oszczędzanie"
            },
            {
              "id": "D",
              "text": "Pewny zysk z inwestycji"
            }
          ],
          "correctAnswer": "B",
          "explanation": "Poduszka to oddzielona rezerwa na nagłe wydatki. Cel dopasuj do sytuacji; mały start jest dobrowolny, bez jednego obowiązkowego progu. Najpierw podstawowe potrzeby i wymagane minimalne spłaty; bez nadwyżki wstrzymaj wpłatę. Sprawdź dostępność i ryzyko; rezerwa nie pokryje automatycznie każdego zdarzenia.",
          "reward": 50,
          "category": "Wyzwanie"
        },
        "en": {
          "id": "c19",
          "question": "Which Polish term means money set aside for unexpected, unplanned expenses?",
          "answers": [
            {
              "id": "A",
              "text": "Pay for current work"
            },
            {
              "id": "B",
              "text": "Poduszka finansowa (emergency reserve)"
            },
            {
              "id": "C",
              "text": "A required loan to fund savings"
            },
            {
              "id": "D",
              "text": "A certain investment profit"
            }
          ],
          "correctAnswer": "B",
          "explanation": "An emergency reserve is kept separately for unexpected expenses. Adapt the goal to your circumstances; a small start is voluntary, with no single mandatory threshold. First protect essential needs and required minimum repayments; without a surplus, pause contributions. Check access and risk; a reserve cannot automatically cover every event.",
          "reward": 50,
          "category": "Deep Dive"
        }
      },
      "wrong_option_explanations": {
        "A": {
          "pl": "Pensja to wpływ za pracę, nie nazwa środków wydzielonych na nagłe wydatki.",
          "en": "Pay is income from work, not the name for funds earmarked for emergencies."
        },
        "C": {
          "pl": "Rezerwa nie oznacza obowiązku zaciągania pożyczki; wpłaty zależą od dostępnej nadwyżki.",
          "en": "A reserve does not require taking a loan; contributions depend on an available surplus."
        },
        "D": {
          "pl": "Cel rezerwy nie oznacza pewnego zysku z inwestycji ani pokrycia każdego ryzyka.",
          "en": "A reserve goal means neither a certain investment profit nor coverage of every risk."
        }
      },
      "source_ids": [
        "cfpb-emergency"
      ],
      "calculation_assumptions": {
        "currency": null,
        "personal_optional_goal": true,
        "no_universal_month_threshold": true,
        "small_start_voluntary_after_essentials_and_required_minimum_repayments": true,
        "no_surplus_pause": true,
        "access_and_risk_need_check": true,
        "no_blanket_event_or_yield_guarantee": true
      }
    },
    {
      "id": "c20",
      "correctAnswer": "C",
      "reward": 50,
      "country": "PL",
      "version": "challenge-evidence-pl-en-v1-c30-draft",
      "author": "daily_author",
      "created_date": "2026-10-16",
      "reviewer": "daily_data_review",
      "learning_goal": "Distinguish stated financial attitudes from knowledge, actual behaviour and financial circumstances.",
      "copy": {
        "pl": {
          "id": "c20",
          "question": "Co w ankiecie opisują postawy wobec pieniędzy?",
          "answers": [
            {
              "id": "A",
              "text": "Liczbę posiadanych produktów"
            },
            {
              "id": "B",
              "text": "Poziom dochodu i stan majątku"
            },
            {
              "id": "C",
              "text": "Deklarowane nastawienie do wydawania, oszczędzania i przyszłości"
            },
            {
              "id": "D",
              "text": "Gwarantowaną zdolność spłaty"
            }
          ],
          "correctAnswer": "C",
          "explanation": "To deklarowane opinie, np. o wydawaniu dziś i oszczędzaniu na przyszłość. Nie są testem wiedzy ani pełnym pomiarem zachowania lub sytuacji finansowej. Same deklaracje nie dowodzą przyczyny trudności ani przyszłego wyniku. Możliwości zależą też od dochodu i koniecznych kosztów; nie oceniaj osoby.",
          "reward": 50,
          "category": "Wyzwanie"
        },
        "en": {
          "id": "c20",
          "question": "What do attitudes towards money describe in a survey?",
          "answers": [
            {
              "id": "A",
              "text": "The number of products owned"
            },
            {
              "id": "B",
              "text": "Income level and wealth"
            },
            {
              "id": "C",
              "text": "Stated views on spending, saving and the future"
            },
            {
              "id": "D",
              "text": "Guaranteed repayment capacity"
            }
          ],
          "correctAnswer": "C",
          "explanation": "These are stated views, such as spending today versus saving for the future. They are not a knowledge test or a full measure of behaviour or financial circumstances. Stated views alone prove neither the cause of difficulties nor a future outcome. Income and essential costs also shape possibilities; avoid judging the person.",
          "reward": 50,
          "category": "Deep Dive"
        }
      },
      "wrong_option_explanations": {
        "A": {
          "pl": "Liczba produktów dotyczy ich posiadania, nie deklarowanych opinii.",
          "en": "Product counts measure ownership, not stated views."
        },
        "B": {
          "pl": "Dochód i majątek opisują zasoby, a nie same postawy; nie należy ich utożsamiać.",
          "en": "Income and wealth describe resources, not attitudes alone; they are distinct measures."
        },
        "D": {
          "pl": "Zdolności spłaty nie gwarantuje deklarowane nastawienie; wymaga ona uwzględnienia rzeczywistych środków i zobowiązań.",
          "en": "Stated attitudes guarantee no repayment capacity, which requires considering actual resources and obligations."
        }
      },
      "source_ids": [
        "oecd-toolkit-2026",
        "cfpb-wellbeing"
      ],
      "calculation_assumptions": {
        "currency": null,
        "new_population_percentage": null,
        "stated_attitudes_separate_from_knowledge_behaviour_resources": true,
        "no_causal_or_future_outcome_guarantee": true,
        "no_culture_or_person_judgment": true
      }
    }
  ],
  "old_claim_assessment": {
    "c16": "OECD2022 printedp16 reports about15% as ofFebruary2022 and6% in2021, with differing wording/context. This is not evidence of a fall from2022 to2021 or a current estimate. Replace decontextualized comparison; do not label both historical figures false.",
    "c17": "Report contains historical13/21. Its gap is not a demonstrated count of lost opportunities or financial outcomes. New21-point scale is explicitly made-up, not currentOECD or21questions.",
    "c18": "Historical46.2% appears in reportp44. The specific psychological-defense/required mindset causal narrative is not established by that survey item. Newscenario is optional and promises no stress effect.",
    "c19": "Existing term is correct; new feedback qualifies personal goal/access/risk and required obligations. No zero-risk statement was reproduced as baseline.",
    "c20": "Historical26.9% and46.9% are reported under that survey method. Newcopy removes stale proportion and cultural diagnosis; current attitude examples do not prove behaviour/resources/causality."
  },
  "voice_checks": {
